static void do_delete_file(SCHISM_UNUSED void *data)
{
	int old_top_file, old_current_file;
	char *ptr;

	if (current_file < 0 || current_file >= flist.num_files)
		return;

	ptr = flist.files[current_file]->path;

	/* would be neat to send it to the trash can if there is one */
	dmoz_path_remove(ptr);

	/* remember the list positions */
	old_top_file = top_file;
	old_current_file = current_file;

	read_directory();

	/* put the list positions back */
	top_file = old_top_file;
	current_file = old_current_file;
	/* edge case: if this was the last file, move the cursor up */
	if (current_file >= flist.num_files)
		current_file = flist.num_files - 1;
	file_list_reposition();
}

static int file_list_handle_text_input(const char *text)
{
	dmoz_file_t* f = flist.files[current_file];
	uint32_t *ucs4;
	size_t i;
	int success;

	/* can't do anything */
	if (search_pos + 1 >= (int)ARRAY_SIZE(search_str))
		return 0;

	if (search_pos < 0) search_pos = 0;

	ucs4 = charset_iconv_easy(text, CHARSET_UTF8, CHARSET_UCS4);
	if (!ucs4)
		return 0;

	success = 1;

	for (i = 0; ucs4[i]; i++) {
		if (ucs4[i] < 32)
			continue;

		if (!(search_pos > 1 || (f && (f->type & TYPE_DIRECTORY))))
			continue;

		if (search_pos + 1 < (int)ARRAY_SIZE(search_str)) {
			search_str[search_pos++] = ucs4[i];
			reposition_at_slash_search();
			status.flags |= NEED_UPDATE;
		}

		success = 1;
	}

	return success;
}

static int file_list_handle_key(struct key_event * k)
{
	int new_file = current_file;

	new_file = CLAMP(new_file, 0, flist.num_files - 1);

	if (!(status.flags & CLASSIC_MODE) && k->sym == SCHISM_KEYSYM_n && (k->mod & SCHISM_KEYMOD_ALT)) {
		if (k->state == KEY_RELEASE)
			song_toggle_multichannel_mode();
		return 1;
	}

	/* The quicksave gestures, so they still work while browsing here -- and
	 * while zoomed into a module as a library, which is exactly where you want
	 * to grab a pattern without first navigating back out.
	 *
	 * They write to cfg_dir_samples, which only ever tracks real directories --
	 * entering a module leaves it on the folder that module lives in -- so the
	 * files land in the folder you were browsing, not inside the module path. */
	if (k->sym == SCHISM_KEYSYM_RIGHT && (k->mod & SCHISM_KEYMOD_SHIFT)
		&& !(k->mod & SCHISM_KEYMOD_ALT)) {
		if (k->state == KEY_RELEASE || k->is_repeat)
			return 1;

		if (k->mod & SCHISM_KEYMOD_CTRL) {
			song_samples_to_quicksave_files();
		} else {
			int pat = (song_get_mode() != MODE_STOPPED)
				? song_get_playing_pattern()
				: get_current_pattern();

			if (pat < 0 || pat >= 200)
				status_text_flash("Nothing playing to quicksave");
			else
				song_pattern_to_quicksave_file(pat);
		}
		return 1;
	}

	if (k->mouse) {
		if (k->x >= 6 && k->x <= 49 && k->y >= 13 && k->y <= 47) {
			search_pos = -1;
			if (k->mouse == MOUSE_SCROLL_UP) {
				new_file -= MOUSE_SCROLL_LINES;
			} else if (k->mouse == MOUSE_SCROLL_DOWN) {
				new_file += MOUSE_SCROLL_LINES;
			} else {
				new_file = top_file + (k->y - 13);
			}
		}
	}
	switch (k->sym) {
	case SCHISM_KEYSYM_UP:           new_file--; search_pos = -1; break;
	case SCHISM_KEYSYM_DOWN:         new_file++; search_pos = -1; break;
	case SCHISM_KEYSYM_PAGEUP:       new_file -= 35; search_pos = -1; break;
	case SCHISM_KEYSYM_PAGEDOWN:     new_file += 35; search_pos = -1; break;
	case SCHISM_KEYSYM_HOME:         new_file = 0; search_pos = -1; break;
	case SCHISM_KEYSYM_END:          new_file = flist.num_files - 1; search_pos = -1; break;

	case SCHISM_KEYSYM_ESCAPE:
		if (search_pos < 0) {
			if (k->state == KEY_RELEASE && NO_MODIFIER(k->mod))
				set_page(PAGE_SAMPLE_LIST);
			return 1;
		} /* else fall through */
	case SCHISM_KEYSYM_RETURN:
		/* Shift-Enter is handled ahead of the search check, and on the press.
		 * Inside it, a pending type-to-find search swallowed the first press to
		 * cancel the search, and falling through on press let the module be
		 * opened as a library instead -- either way it took two goes. */
		if (k->mod & SCHISM_KEYMOD_SHIFT) {
			if (k->state == KEY_PRESS && !k->is_repeat)
				handle_shift_enter_key();
			search_pos = -1;
			return 1;
		}
		if (search_pos < 0) {
			if (k->state == KEY_PRESS)
				return 0;
			handle_enter_key();
			search_pos = -1;
		} else {
			if (k->state == KEY_PRESS)
				return 1;
			search_pos = -1;
			status.flags |= NEED_UPDATE;
			return 1;
		}
		return 1;
	case SCHISM_KEYSYM_DELETE:
		if (k->state == KEY_RELEASE)
			return 1;
		search_pos = -1;
		if (flist.num_files > 0)
			dialog_create(DIALOG_OK_CANCEL, "Delete file?", do_delete_file, NULL, 1, NULL);
		return 1;
	case SCHISM_KEYSYM_BACKSPACE:
		if (search_pos > -1) {
			if (k->state == KEY_RELEASE)
				return 1;
			search_pos--;
			status.flags |= NEED_UPDATE;
			reposition_at_slash_search();
			return 1;
		}
		SCHISM_FALLTHROUGH;
	case SCHISM_KEYSYM_SLASH:
		if (search_pos < 0) {
			if (k->state == KEY_PRESS)
				return 0;
			search_pos = 0;
			status.flags |= NEED_UPDATE;
			return 1;
		}
		SCHISM_FALLTHROUGH;
	default:
		if (k->text)
			file_list_handle_text_input(k->text);

		if (!k->mouse) return 0;
	}

	if (k->mouse == MOUSE_CLICK) {
		if (k->state != KEY_PRESS)
			return 0;
	} else if (k->mouse == MOUSE_DBLCLICK) {
		handle_enter_key();
		return 1;
	} else {
		/* prevent moving the cursor twice from a single key press */
		if (k->state == KEY_RELEASE)
			return 1;
	}

	new_file = CLAMP(new_file, 0, flist.num_files - 1);
	if (new_file != current_file) {
		if (fake_slot != KEYJAZZ_NOINST && fake_slot_changed) {
			will_move_to = new_file;
			dialog_create(DIALOG_YES_NO,
				"Discard Changes?",
				do_discard_changes_and_move,
				NULL,
				0, NULL);
			return 1;
			/* support saving? XXX */
			/*"Save Sample?" OK Cancel*/
			/*"Discard Changes?" OK Cancel*/
		}
		fake_slot = KEYJAZZ_NOINST;
		fake_slot_changed = 0;
		search_pos = -1;
		current_file = new_file;
		file_list_reposition();
		status.flags |= NEED_UPDATE;
	}
	return 1;
}

static void load_sample_handle_key(struct key_event * k)
{
	int n, v;

	if (k->state == KEY_PRESS && k->sym == SCHISM_KEYSYM_ESCAPE && NO_MODIFIER(k->mod)) {
		set_page(PAGE_SAMPLE_LIST);
		return;
	}
	if (!NO_MODIFIER(k->mod)) return;

	if (k->midi_note > -1) {
		n = k->midi_note;
		if (k->midi_volume > -1) {
			v = k->midi_volume / 2;
		} else {
			v = KEYJAZZ_DEFAULTVOL;
		}
	} else if (k->is_repeat) {
		return;
	} else {
		n = kbd_get_note(k);
		v = KEYJAZZ_DEFAULTVOL;
		if (n <= 0 || n > 120)
			return;
	}

	handle_preload();
	if (fake_slot != KEYJAZZ_NOINST) {
		if (k->state == KEY_PRESS)
			song_keydown(KEYJAZZ_INST_FAKE, KEYJAZZ_NOINST, n, v, KEYJAZZ_CHAN_CURRENT);
		else
			song_keyup(KEYJAZZ_INST_FAKE, KEYJAZZ_NOINST, n);
	}
}

