/* Shift-Enter on a module row: lift every sample in it into consecutive slots,
 * starting at the currently selected one. Ported from the impulse-tracker
 * fork's Shift-Enter bulk load.
 *
 * The module is loaded into its own song and the samples deep-copied out of it
 * (song_copy_sample allocates), so freeing it afterwards is safe. */
/* Load every sample in the list currently on screen -- the samples of a module we
 * are zoomed into, or every sample file in the folder being browsed. Entries that
 * have already been read carry their sample with them; the rest are loaded from
 * their path. */
static void handle_shift_enter_load_list(const char *what)
{
	song_sample_t *smp;
	int n, cur, loaded = 0, skipped = 0;

	cur = sample_get_current();

	for (n = 0; n < flist.num_files; n++) {
		dmoz_file_t *f = flist.files[n];

		if (!f)
			continue;

		dmoz_fill_ext_data(f);

		if (cur >= MAX_SAMPLES) {
			skipped++;
			continue;
		}

		if (f->sample) {
			void *ptr;

			song_copy_sample(cur, f->sample);
			smp = song_get_sample(cur);
			strncpy(smp->name, f->title ? f->title : "", ARRAY_SIZE(smp->name) - 1);
			smp->name[ARRAY_SIZE(smp->name) - 1] = '\0';
			ptr = f->base
				? charset_iconv_easy(f->base, CHARSET_CHAR, CHARSET_CP437)
				: NULL;
			if (ptr) {
				strncpy(smp->filename, ptr, ARRAY_SIZE(smp->filename) - 1);
				free(ptr);
			}
			smp->filename[ARRAY_SIZE(smp->filename) - 1] = '\0';
		} else if ((f->type & TYPE_SAMPLE_MASK) && f->path) {
			if (!song_load_sample(cur, f->path))
				continue;
		} else {
			continue; /* a directory, a module, something we can't use */
		}

		finish_load(cur);
		loaded++;
		cur++;
	}

	memused_songchanged();

	if (!loaded) {
		status_text_flash("No samples in %s", what);
		return;
	}

	status.flags |= SONG_NEEDS_SAVE;
	if (skipped)
		status_text_flash("Loaded %d samples (%d didn't fit)", loaded, skipped);
	else
		status_text_flash("Loaded %d samples from %s", loaded, what);
	/* stay put: bulk loading is something you do repeatedly while browsing, and
	 * being thrown onto the sample list after each one just means walking back */
	status.flags |= NEED_UPDATE;
}

static void handle_shift_enter_key(void)
{
	dmoz_file_t *file;
	song_t *mod;
	song_sample_t *smp;
	int cur, n, loaded = 0, skipped = 0;

	if (current_file < 0 || current_file >= flist.num_files)
		return;

	/* Zoomed into a module: its samples are the list in front of us. */
	if (_library_mode) {
		handle_shift_enter_load_list("this library");
		return;
	}

	file = flist.files[current_file];
	dmoz_cache_update(cfg_dir_samples, &flist, NULL);
	dmoz_fill_ext_data(file);

	/* Anything that opens as a library and isn't itself a sample is worth trying
	 * as a module -- going by TYPE_MODULE_MASK alone depends on the type bits
	 * having been filled in for this row already. If it turns out not to load,
	 * fall back to taking the whole folder, which is the same idea. */
	mod = ((file->type & TYPE_MODULE_MASK)
			|| ((file->type & TYPE_BROWSABLE_MASK)
				&& !(file->type & (TYPE_SAMPLE_MASK | TYPE_INST_MASK))
				&& file->type != TYPE_DIRECTORY))
		? song_create_load(file->path)
		: NULL;

	if (!mod) {
		handle_shift_enter_load_list("this folder");
		return;
	}

	cur = sample_get_current();
	for (n = 1; n < MAX_SAMPLES; n++) {
		if (!mod->samples[n].data || !mod->samples[n].length)
			continue; /* empty slot in the source module */

		if (cur >= MAX_SAMPLES) {
			skipped++;
			continue;
		}

		song_copy_sample(cur, mod->samples + n);
		smp = song_get_sample(cur);
		/* keep the module's own name and filename for the slot */
		memcpy(smp->name, mod->samples[n].name, sizeof(smp->name));
		smp->name[ARRAY_SIZE(smp->name) - 1] = '\0';
		memcpy(smp->filename, mod->samples[n].filename, sizeof(smp->filename));
		smp->filename[ARRAY_SIZE(smp->filename) - 1] = '\0';

		loaded++;
		cur++;
	}

	csf_free(mod);

	if (!loaded) {
		status_text_flash("%s contains no samples", file->base);
		return;
	}

	memused_songchanged();
	status.flags |= SONG_NEEDS_SAVE;
	if (skipped)
		status_text_flash("Loaded %d samples (%d didn't fit)", loaded, skipped);
	else
		status_text_flash("Loaded %d samples from %s", loaded, file->base);
	/* stay in the browser -- see above */
	status.flags |= NEED_UPDATE;
}

